// Normalises iClosed contacts into booking_recovery rows.
//
// Emits status='backfilled', deliberately NOT 'pending'. The dispatcher only
// reads 'pending', so nothing here can send. That is the point: this sweep
// may surface a large pool of old abandoned leads, and quietly emailing all
// of them the moment a reconciler is switched on would be a cold blast sent
// by accident. Count them first, then promote on purpose.

const MAX_AGE_DAYS = 90;   // older than this is not worth a row

const body = $input.first().json;
const list = Array.isArray(body) ? body
  : (body.data || body.contacts || body.results || body.items || []);
if (!Array.isArray(list)) throw new Error('unexpected API shape: ' + JSON.stringify(body).slice(0, 300));

const cap = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const pick = (...vals) => { for (const v of vals) { const s = cap(v, 300); if (s) return s; } return ''; };
const now = new Date();
const out = [];

for (const c of list) {
  // latestCall is iClosed's never-booked discriminator.
  const latestCall = c.latestCall || c.latest_call || null;
  if (latestCall && typeof latestCall === 'object' && Object.keys(latestCall).length) continue;

  const status = pick(c.status, c.contactStatus).toLowerCase();
  if (status && status !== 'potential' && status !== 'qualified') continue;

  const joined = new Date(pick(c.joinedTime, c.joined_time, c.createdAt, c.created_at));
  if (!isNaN(joined) && (now - joined) / 86400000 > MAX_AGE_DAYS) continue;

  let email = pick(c.email, c.emailAddress).toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) email = '';

  let phone = '';
  const rawPhone = pick(c.phoneNumber, c.phone, c.mobile).replace(/[^0-9+]/g, '');
  if (rawPhone) {
    const d = rawPhone.replace(/\+/g, '');
    if (rawPhone.startsWith('+')) phone = '+' + d;
    else if (d.length === 10) phone = '+1' + d;
    else if (d.length === 11 && d.startsWith('1')) phone = '+' + d;
  }
  if (phone && !/^\+[1-9][0-9]{7,14}$/.test(phone)) phone = '';
  if (!email && !phone) continue;

  let first = pick(c.firstName, c.first_name);
  const full = pick(c.name, c.fullName);
  if (!first && full) first = full.split(/\s+/)[0] || '';
  if (!(first.length >= 2 && !/[0-9@]/.test(first))) first = '';
  if (first && (first === first.toLowerCase() || first === first.toUpperCase())) {
    first = first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
  }

  const t = c.tracking || c.utm || {};
  const nowIso = now.toISOString();

  out.push({ json: {
    lead_key: pick(c.id, c.previewId, c.contactId) || email || phone,
    iclosed_contact_id: pick(c.id, c.previewId, c.contactId),
    email,
    phone,
    first_name: first,
    last_name: pick(c.lastName, c.last_name),
    timezone: pick(c.timeZone, c.timezone),
    iclosed_status: status,
    utm_source: cap(t.utm_source || t.utmSource, 120),
    utm_medium: cap(t.utm_medium || t.utmMedium, 120),
    utm_campaign: cap(t.utm_campaign || t.utmCampaign, 200),
    utm_content: cap(t.utm_content || t.utmContent, 200),
    fbclid: cap(t.fbclid, 300),
    status: 'backfilled',
    suppressed_reason: 'awaiting_review',
    follow_up_due_at: '',
    created_at: !isNaN(joined) ? joined.toISOString() : nowIso,
    updated_at: nowIso
  } });
}

return out;
